import { Checks } from './Checks';
import { StepLog } from './StepLog';

/** One row of a file: its fields by the header's names, and where it is. */
export type Row = { file: string; line: number; fields: Record<string, string> };

/**
 * The team's test data (G-154): CSV files in cypress/data/, a header row naming the fields. The
 * environment (--expose environment=staging, or ENVIRONMENT) looks in cypress/data/staging/ first,
 * then in cypress/data/. Read and handed out in Node (cypress.config.ts), where every spec of a run
 * sees the same files and the same queue. Two kinds:
 * - reusable('policies.csv'): rows any test may read, as often as it likes;
 * - consumable('new-accounts.csv'): one row each time it is asked, never the same row twice in a run (a
 *   row a failed test took stays taken). None left: the test is skipped, saying so (Checks.assume). The
 *   run's report says how many rows each file gave.
 */
export const TestData = {
  /** Every row of the file, for any test to read. */
  reusable(file: string): Cypress.Chainable<Row[]> {
    return cy.task('testDataRows', file, { log: false }) as unknown as Cypress.Chainable<Row[]>;
  },

  /** The next row no test of this run has taken; the test is skipped, saying why, when none is left. */
  consumable(file: string): Cypress.Chainable<Row> {
    return cy.task('testDataTake', file, { log: false }).then((taken) => {
      const { row, why } = taken as { row: Row | null; why: string };
      Checks.assume(row !== null, why);
      if (row) StepLog.note(`test data: ${row.file}, line ${row.line}`);
      return cy.wrap(row as Row, { log: false });
    });
  },

  /** The row's field of this name; fails naming the file and its fields when the header has no such name. */
  field(row: Row, name: string): string {
    const value = row.fields[name];
    if (value === undefined) throw new Error(`${row.file} has no field "${name}": its header names ${Object.keys(row.fields).join(', ')}`);
    return value;
  },

  // ==== YOURS (extras): safe to edit; regenerating keeps what is between these lines ====
  // A value of your own from a row, for tests that read like the story:
  // policyWithAmountDue(): Cypress.Chainable<string> {
  //   return TestData.consumable('policies-due.csv').then((row) => TestData.field(row, 'number'));
  // },
  // ==== END YOURS (extras) ====
};
